QUARANTINE_BACKFILL = 'pf4_pf4_tenant_and_financial_guards'


def _candidate_tenant_ids(user_id, CoreTenant, TenantMember, UserProfile):
    """Tập tenant id mà user thực sự thuộc: owner + UserProfile + TenantMember.

    KHÔNG dùng `Portfolio.tenant` ở đây: broker config không gắn với portfolio,
    nên tín hiệu duy nhất đáng tin là membership.
    """
    ids = set(
        CoreTenant.objects.filter(owner_user_id=user_id).values_list('id', flat=True)
    )
    ids.update(
        UserProfile.objects.filter(user_id=user_id)
        .exclude(tenant__isnull=True)
        .values_list('tenant_id', flat=True)
    )
    ids.update(
        TenantMember.objects.filter(user_id=user_id).values_list('tenant_id', flat=True)
    )
    return ids


def _quarantine(QuarantinedRecord, model_name, original_id, payload, reason):
    """Ghi 1 bản ghi quarantine. Trả False nếu đã có ⇒ idempotent."""
    existing = QuarantinedRecord.objects.filter(
        model_name=model_name, original_id=original_id
    ).first()
    if existing is not None:
        return False
    QuarantinedRecord.objects.create(
        model_name=model_name,
        original_id=original_id,
        data=payload,
        reason=f'[{QUARANTINE_BACKFILL}] {reason}',
    )
    return True


def backfill_broker_config_tenant(apps, schema_editor):
    """TEN-04 — gán `UserBrokerConfig.tenant`.

    Ownership decision (KHÔNG đoán):
    - user thuộc đúng 1 tenant  ⇒ gán tenant đó.
    - user thuộc ≥2 tenant       ⇒ ambiguous ⇒ `tenant` giữ NULL + `QuarantinedRecord`.
    - user không thuộc tenant nào ⇒ không tạo tenant ⇒ `QuarantinedRecord`.

    Chỉ xử lý row `tenant IS NULL` ⇒ chạy lại không đổi kết quả (idempotent).
    """
    UserBrokerConfig = apps.get_model('user_workspace', 'UserBrokerConfig')
    QuarantinedRecord = apps.get_model('user_workspace', 'QuarantinedRecord')
    CoreTenant = apps.get_model('identity_access', 'CoreTenant')
    TenantMember = apps.get_model('identity_access', 'TenantMember')
    UserProfile = apps.get_model('identity_access', 'UserProfile')

    assigned = quarantined = unresolved = 0
    for config in (
        UserBrokerConfig.objects.filter(tenant__isnull=True)
        .order_by('pk')
        .iterator()
    ):
        candidates = _candidate_tenant_ids(
            config.user_id, CoreTenant, TenantMember, UserProfile)
        if len(candidates) == 1:
            config.tenant_id = next(iter(candidates))
            config.save(update_fields=['tenant'])
            assigned += 1
            continue
        if candidates:
            reason = (
                f'ambiguous: user {config.user_id} thuộc {len(candidates)} tenant '
                f'{sorted(candidates)} — không tự chọn tenant.'
            )
        else:
            reason = (
                f'user {config.user_id} chưa thuộc tenant nào (không có '
                'CoreTenant.owner / UserProfile.tenant / TenantMember) — không tự tạo tenant.'
            )
        if _quarantine(
            QuarantinedRecord, 'UserBrokerConfig', config.pk,
            {
                'user_id': config.user_id,
                'provider': config.provider,
                'label': config.label,
                'candidate_tenant_ids': sorted(candidates),
            },
            reason,
        ):
            quarantined += 1
        unresolved += 1

    print(
        'backfill_broker_config_tenant: '
        f'assigned={assigned} quarantined={quarantined} unresolved={unresolved}'
    )


